		/* smov Rw(dst_reg), Rv(src_reg-IR_REG_FP_FIRST).b[lane] */
		return 0x0e002c00 | dst_reg | ((src_reg-IR_REG_FP_FIRST) << 5) |
			(((lane << 1) | 0x1) << 16);
